(function(){'use strict';
/* Diagnostics Database generator — jahdb-diagnostics-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-DIAGNOSTICS-';
var SRC='public';
var RECORD_KIND='diagnostics record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"The Diagnostic Process","brief":"Diagnostics is systematic problem-solving: gather symptoms, form hypotheses, test, and verify — in medicine, machines, and systems.","points":["Start with symptoms: what, when, and under what conditions.","Form hypotheses ranked by likelihood and testability.","Test to eliminate: each test should rule hypotheses in or out.","Verify the fix: confirm the symptom is gone and nothing else broke."],"examples":["A mechanic reproducing a noise before touching a wrench.","A doctor ruling out common causes before ordering rare tests."],"history":["Hippocratic medicine systematized clinical observation.","Engineering troubleshooting formalized the method in the 20th century."],"uses":["Every repair trade and profession.","Medicine and healthcare.","IT and systems troubleshooting."],"qa":[["What's the biggest diagnostic mistake?","Replacing parts (or prescribing) before confirming the cause."],["How do I get better at diagnosing?","Practice the process deliberately; experience builds pattern recognition."],["When should I stop testing?","When the evidence converges and the fix verifies — not before."]]},{"title":"Differential Diagnosis","brief":"Differential diagnosis lists all plausible causes of symptoms, then narrows by testing — medicine's core reasoning method.","points":["Generate broadly first: common, serious, and can't-miss causes.","Prioritize by probability and danger — rule out the dangerous first.","Tests should discriminate: each result should change the ranking.","Revisit the list when new information arrives."],"examples":["Chest pain worked up for cardiac causes before reflux.","A fever differential narrowing with lab results."],"history":["Formalized in 19th-century clinical medicine.","Decision-support tools now assist the process."],"uses":["Clinical medicine.","Teaching diagnostic reasoning.","Reducing diagnostic error."],"qa":[["Why do doctors order so many tests?","To rule out dangerous causes — the cost of missing exceeds the cost of testing."],["Can patients help?","Yes — accurate histories dramatically improve diagnosis."],["What causes misdiagnosis?","Premature closure, anchoring, and incomplete histories."]]},{"title":"Root Cause Analysis","brief":"Root cause analysis digs past symptoms to the underlying reason failures happen — so fixes last.","points":["Symptoms are effects; RCA finds the cause that, fixed, prevents recurrence.","Ask 'why' repeatedly until reaching a controllable cause.","Distinguish root causes from contributing factors.","Fix the system, not just the symptom — and verify."],"examples":["Repeated pump failures traced to cavitation from an undersized suction line.","Recurring outages traced to a change process, not the failed component."],"history":["Toyota's production system popularized systematic RCA.","Aviation and nuclear industries formalized it after disasters."],"uses":["Manufacturing quality.","IT incident postmortems.","Healthcare safety."],"qa":[["How deep should I go?","Until you reach something you can actually change."],["RCA vs blame?","RCA fixes systems; blame fixes nothing — keep it blameless."],["What tools help?","5 Whys, fishbone diagrams, fault trees."]]},{"title":"Fault Tree Analysis","brief":"Fault trees map how component failures combine to cause system failures — top-down logic for critical systems.","points":["Start with the undesired top event, then branch into causes with AND/OR logic.","AND gates need all inputs; OR gates need any — quantifying risk.","Minimal cut sets reveal the smallest failure combinations.","Used where failure is unacceptable: aerospace, nuclear, medical."],"examples":["An aircraft system's fault tree showing dual failures needed for hazard.","A chemical plant identifying single points of failure."],"history":["Developed at Bell Labs (1960s) for missile systems.","Adopted across safety-critical industries."],"uses":["Safety engineering.","Reliability quantification.","Regulatory safety cases."],"qa":[["Is it hard to learn?","The logic is simple; completeness takes expertise."],["Fault tree vs FMEA?","Fault trees work top-down from failures; FMEA works bottom-up from components."],["Software too?","Yes — adapted for software safety analysis."]]},{"title":"Failure Mode and Effects Analysis (FMEA)","brief":"FMEA systematically lists how each component can fail, the effects, and the risk — before failures happen.","points":["For each component: failure modes, effects, causes, and current controls.","Risk priority numbers (severity × occurrence × detection) rank action.","Design FMEA targets products; process FMEA targets manufacturing.","Living document: update as designs and processes change."],"examples":["An automotive FMEA catching a single-point brake failure in design.","A process FMEA preventing assembly errors."],"history":["Military origins (1940s-50s); automotive standardized it (QS-9000).","Healthcare adapted it for patient safety."],"uses":["Product design risk reduction.","Manufacturing quality.","Healthcare and aerospace safety."],"qa":[["Is FMEA worth the effort?","For critical systems, absolutely — it finds issues cheapest in design."],["How detailed?","Enough to drive action; analysis paralysis helps no one."],["Who should participate?","Cross-functional teams — designers, manufacturing, quality."]]},{"title":"The 5 Whys","brief":"The 5 Whys technique asks 'why' repeatedly to peel symptoms back to root causes — simple and powerful.","points":["Start with the problem statement, then ask why five times (or as needed).","Each answer must be factual, not speculative.","Stop at a cause you can act on.","Beware single-cause bias — real problems often have several roots."],"examples":["Late deliveries → why? → scheduling → why? → no capacity planning → fix planning.","A defect traced to a worn fixture, not operator error."],"history":["Toyota Production System (1950s-70s); Taiichi Ohno popularized it.","Spread to Lean, Agile, and IT postmortems."],"uses":["Quick incident analysis.","Manufacturing problem-solving.","Team retrospectives."],"qa":[["Always exactly five?","No — five is a rule of thumb; stop at an actionable cause."],["What are its limits?","It can oversimplify; pair with broader methods for complex failures."],["Who should ask?","Those closest to the work, facilitated neutrally."]]},{"title":"Fishbone Diagrams (Ishikawa)","brief":"Fishbone diagrams organize possible causes into categories — visualizing brainstorming for structured analysis.","points":["Classic categories: man, machine, method, material, measurement, environment (6Ms).","Head states the problem; bones branch into cause categories.","Teams brainstorm causes under each bone, then prioritize.","Best for organizing many possible causes before testing."],"examples":["A quality team mapping defect causes across the 6Ms.","A clinic mapping delayed discharges by category."],"history":["Kaoru Ishikawa developed it in the 1960s for quality control.","Six Sigma adopted it widely."],"uses":["Quality problem-solving.","Team brainstorming structure.","Teaching causal thinking."],"qa":[["When is it useful?","When many possible causes need organizing before testing."],["Does it find the answer?","It organizes hypotheses; testing finds answers."],["What categories for services?","Adapt: people, process, policy, place, etc."]]},{"title":"Medical History Taking","brief":"The patient history is diagnosis's most powerful tool — most diagnoses come from history alone.","points":["Chief complaint in the patient's own words opens every encounter.","OPQRST (onset, provokes, quality, radiates, severity, time) structures symptom inquiry.","Past history, medications, and social history complete the picture.","Listen first — interrupting early loses critical information."],"examples":["A history revealing the chest pain is reflux, not cardiac.","Medication review explaining new symptoms."],"history":["Hippocratic history-taking is 2,400 years old.","Structured formats (SOAP) organized it in the 1960s."],"uses":["Every clinical encounter.","Reducing unnecessary testing.","Building therapeutic relationships."],"qa":[["How much comes from history?","Studies suggest 70-80% of diagnoses."],["What should patients prepare?","Symptom timeline, medications, and questions."],["Why do doctors seem rushed?","System pressures — but good history saves time overall."]]},{"title":"Physical Examination","brief":"The physical exam — inspection, palpation, percussion, auscultation — grounds diagnosis in the body.","points":["Inspection: what you see — rashes, swelling, asymmetry.","Palpation: what you feel — masses, tenderness, pulses.","Percussion and auscultation: what you hear — lungs, heart, bowels.","Focused exams target the complaint; complete exams screen broadly."],"examples":["An exam finding the murmur that explains syncope.","Palpation locating the exact tender spot."],"history":["Laennec's stethoscope (1816) transformed examination.","Evidence-based exam research refined techniques."],"uses":["Clinical diagnosis.","Screening and prevention.","Monitoring chronic disease."],"qa":[["Is the exam obsolete with imaging?","No — it guides what imaging to order and catches what machines miss."],["What should patients expect?","Explanation, privacy, and consent throughout."],["Can I examine myself?","Self-exams (breast, testicular, skin) are valuable screening."]]},{"title":"Laboratory Diagnostics","brief":"Lab medicine interprets blood, urine, and tissue tests — turning samples into diagnoses.","points":["Pre-analytical errors (collection, labeling) cause most lab mistakes.","Reference ranges are population guides; personal baselines matter.","Sensitivity and specificity determine what results mean.","Trends over time beat single snapshots."],"examples":["Serial troponins diagnosing a heart attack.","A1c trends guiding diabetes management."],"history":["Clinical labs professionalized in the 20th century.","Automation and point-of-care expanded access."],"uses":["Disease diagnosis and monitoring.","Screening and prevention.","Treatment guidance."],"qa":[["Why repeat tests?","To confirm, track trends, and catch lab error."],["Fasting — why?","Food alters glucose, lipids, and other analytes."],["Can I order my own labs?","Direct-to-consumer testing exists; interpretation needs clinicians."]]},{"title":"Medical Imaging Diagnostics","brief":"Imaging lets clinicians see inside: X-ray, CT, MRI, ultrasound — each with strengths and trade-offs.","points":["Choose by question: bone (X-ray/CT), soft tissue (MRI), real-time (ultrasound).","Radiation dose matters — justify every exposure.","Incidental findings are common; correlate clinically.","The radiologist's read plus clinical context makes the diagnosis."],"examples":["CT finding appendicitis when the exam was equivocal.","MRI characterizing a brain lesion."],"history":["X-ray (1895) → CT (1970s) → MRI (1980s) → each transformed medicine.","AI now assists detection."],"uses":["Diagnosis across specialties.","Treatment planning and guidance.","Screening programs."],"qa":[["Which scan do I need?","Depends on the question — your doctor matches modality to anatomy."],["Are incidental findings bad?","They're common; most are benign but need clinical correlation."],["Will AI replace radiologists?","It augments detection; judgment remains human."]]},{"title":"Pathology","brief":"Pathology diagnoses disease from tissues and cells — the definitive answer in cancer and more.","points":["Biopsies provide tissue; pathologists render the diagnosis.","Histology (microscopic structure) and cytology (cells) are the core methods.","Molecular pathology adds genetic testing for targeted therapy.","Turnaround time matters — frozen sections guide surgery in real time."],"examples":["A biopsy distinguishing benign from malignant.","Molecular testing matching a tumor to targeted therapy."],"history":["Virchow founded cellular pathology (1858).","Immunohistochemistry and genomics modernized it."],"uses":["Cancer diagnosis.","Surgical guidance.","Treatment selection."],"qa":[["Why does pathology take time?","Processing, staining, and expert review — accuracy over speed."],["Can I get a second opinion?","Yes — pathology second opinions are common and wise for major diagnoses."],["What is a frozen section?","Rapid analysis during surgery to guide the operation."]]},{"title":"Automotive Diagnostics Process","brief":"Systematic car diagnosis: verify the complaint, check basics, follow data, test components.","points":["Reproduce the symptom first — no symptom, no diagnosis.","Check basics: battery, fluids, obvious damage — before deep tests.","Codes guide; live data and physical tests confirm.","One change at a time, then verify."],"examples":["A no-start traced to a corroded ground, not the starter.","Intermittent stalling caught via logged data."],"history":["OBD-II (1996) standardized the starting point.","Process discipline separates pros from parts-swappers."],"uses":["Professional repair.","DIY troubleshooting.","Pre-purchase inspection."],"qa":[["Where do I start?","Verify, check basics, read codes, test — in that order."],["Why do shops charge for diagnosis?","Because skill and equipment find the real cause, saving parts cost."],["Can I diagnose with just a code reader?","Start yes; finish often needs deeper tools."]]},{"title":"Electrical Troubleshooting Method","brief":"Electrical diagnosis follows the circuit: power, ground, load, and control — methodically.","points":["Half-splitting: test the middle to eliminate half the circuit.","Voltage drop testing finds bad connections under load.","Never assume ground is good — test it.","Schematics are the map; learn to read them."],"examples":["A voltage-drop test finding a corroded connection.","Half-splitting isolating a short in minutes."],"history":["Methodical troubleshooting replaced guesswork as systems complexified.","Training programs formalized the approaches."],"uses":["Automotive, HVAC, and industrial electrical.","Home wiring diagnosis.","Electronics repair."],"qa":[["What's the first step?","Understand the circuit — get the schematic."],["Why test under load?","Bad connections hide without current flowing."],["Multimeter or test light?","Meters for accuracy; test lights for quick power checks."]]},{"title":"Network Troubleshooting","brief":"Network diagnosis layers the problem: physical, link, network, transport, application — bottom up.","points":["Start at layer 1: cables, lights, link — most issues live here.","Ping tests connectivity; traceroute finds where it breaks.","DNS causes a huge share of 'internet is down'.","Change one thing at a time; document as you go."],"examples":["A DNS change fixing 'the internet is down'.","A bad cable found by layer-1 checks."],"history":["The OSI model (1980s) gave troubleshooting its layers.","Methodology matured with enterprise networking."],"uses":["IT support.","Home network fixes.","Infrastructure reliability."],"qa":[["Where do I start?","Physical layer — cables and lights — then up the stack."],["Why is DNS always the answer?","Because name resolution fails in confusing ways."],["What tools?","Ping, traceroute, and a cable tester cover most."]]},{"title":"Software Debugging","brief":"Debugging is diagnosis for code: reproduce, isolate, hypothesize, fix, verify.","points":["Reproduce reliably first — intermittent bugs need logging.","Bisect: narrow the change or input that triggers it.","Read the error — really read it — before searching.","Rubber-ducking: explaining the code often reveals the bug."],"examples":["A bisect finding the exact commit that broke the build.","A log revealing a race condition."],"history":["Debugging is as old as programming (grace Hopper's moth, 1947).","Debuggers, profilers, and observability matured the craft."],"uses":["Software development.","Production incident response.","Performance tuning."],"qa":[["What's the best debugging skill?","Systematic hypothesis testing — not guessing."],["Why can't I find it?","Take a break; fresh eyes see what tired ones miss."],["Print statements or debugger?","Both — prints for flow, debuggers for state."]]},{"title":"Log Analysis","brief":"Logs are systems' diaries: analysis finds errors, patterns, and causes in the noise.","points":["Centralize logs — scattered logs can't be correlated.","Timestamps must agree — NTP everywhere.","Search for errors around the incident time, then widen.","Structure logs (JSON) for machine analysis."],"examples":["Correlating app errors with a database failover via timestamps.","A log pattern revealing a daily cron failure."],"history":["Syslog (1980s) standardized; ELK (2010s) made analysis accessible.","Observability platforms unified logs, metrics, traces."],"uses":["Incident diagnosis.","Security investigation.","Performance analysis."],"qa":[["Where do I start?","Centralize, ensure time sync, then search around incidents."],["Too many logs?","Filter by severity and time; aggregate ruthlessly."],["What should I log?","Errors with context, key transactions, and state changes."]]},{"title":"Performance Diagnostics","brief":"Performance diagnosis finds bottlenecks: measure first, then optimize the constraint.","points":["Profile before optimizing — intuition about bottlenecks is usually wrong.","The bottleneck moves: fix one, measure again.","Distinguish latency from throughput problems.","Load test realistically — production-like data and traffic."],"examples":["Profiling revealing a database query, not code, as the bottleneck.","Load testing finding the connection-pool limit."],"history":["Profilers (1970s+) and APM (2000s) instrumented the process.","Observability made production profiling safe."],"uses":["Application tuning.","Capacity planning.","User experience improvement."],"qa":[["Where's the bottleneck?","Measure — CPU, memory, IO, network, locks — don't guess."],["Should I micro-opt?","Only measured hot spots; clarity first elsewhere."],["What is APM?","Application performance monitoring — production instrumentation."]]},{"title":"HVAC Diagnostics","brief":"HVAC diagnosis: airflow, refrigerant, electrical, and controls — comfort depends on all four.","points":["Check airflow first — most comfort issues are airside.","Refrigerant charge needs gauges and temperatures, not guessing.","Electrical: capacitors and contactors are common failures.","Thermostats and controls cause surprising share of 'no cool' calls."],"examples":["A weak capacitor found behind a no-cool call.","Low airflow traced to a collapsed duct."],"history":["Refrigeration cycle understanding (early 20th c.) grounded the trade.","Electronic diagnostics modernized fieldwork."],"uses":["Home comfort.","Energy efficiency.","Equipment longevity."],"qa":[["Why isn't my AC cooling?","Airflow, charge, electrical, controls — check in order."],["Can I add refrigerant myself?","Regulations and risk say call a pro."],["How often service?","Annually — prevention beats repair."]]},{"title":"Plumbing Diagnostics","brief":"Plumbing diagnosis traces water: pressure, flow, leaks, and drainage — following the pipes.","points":["Low pressure: fixture, branch, or main? Isolate by testing points.","Leaks: visible, meter-tested, or acoustic/thermal located.","Slow drains: fixture trap, branch, or main line? Camera scopes decide.","Water quality issues point to source or plumbing materials."],"examples":["A meter test proving a slab leak.","A camera finding root intrusion in the main."],"history":["Plumbing is ancient; diagnostic cameras (1990s+) transformed it.","Acoustic and thermal tools refined leak location."],"uses":["Leak detection and repair.","Drain troubleshooting.","Water quality investigation."],"qa":[["How do I find a hidden leak?","Meter test, then acoustic/thermal location — then open minimally."],["Chemical drain cleaners?","They damage pipes; mechanical clearing is better."],["When call a plumber?","Main lines, gas, and anything behind walls."]]},{"title":"Structural Diagnostics","brief":"Structural diagnosis assesses buildings: cracks, settlement, and load paths — safety first.","points":["Crack patterns tell stories: vertical (shrinkage), diagonal (settlement), horizontal (pressure).","Monitor before concluding — some movement is seasonal.","Load path understanding separates cosmetic from structural.","Engineers, not inspectors, judge structural safety."],"examples":["Monitoring distinguishing seasonal movement from progressive settlement.","A horizontal foundation crack triggering engineering review."],"history":["Structural engineering (19th-20th c.) gave assessment its science.","Monitoring instruments quantified what eyes suspected."],"uses":["Homebuyer safety.","Maintenance planning.","Post-disaster assessment."],"qa":[["Which cracks matter?","Horizontal, widening, or displacing — get an engineer."],["Can I monitor myself?","Crack gauges and photos over seasons — then consult."],["When is it urgent?","Sudden changes, displacement, or water intrusion with cracks."]]},{"title":"Vibration Diagnostics","brief":"Vibration analysis as a diagnostic discipline: reading machine health from its shake.","points":["Every fault has a frequency signature — learn the vocabulary.","Baseline when healthy; trends reveal degradation.","Route-based programs cover plants systematically.","Combine with temperature, oil, and ultrasound for confidence."],"examples":["A bearing fault trended for months, replaced on schedule.","Resonance identified as the real culprit behind 'imbalance'."],"history":["FFT analyzers (1970s-80s) made it practical.","ISO standards codified severity."],"uses":["Predictive maintenance.","Commissioning verification.","Troubleshooting chronic issues."],"qa":[["Do I need training?","Yes — interpretation is the skill."],["What equipment?","Start with a good data collector and software."],["How often measure?","Monthly for critical, quarterly for general — trend-dependent."]]},{"title":"Thermal Diagnostics","brief":"Infrared thermography as diagnosis: finding faults by their heat signatures.","points":["Electrical hotspots precede failures by weeks or months.","Mechanical friction shows as heat before vibration sometimes.","Building envelopes reveal insulation and moisture via temperature.","Emissivity and reflections are the classic pitfalls."],"examples":["A hot connection found during a routine scan, fixed before failure.","Missing insulation mapped across a building."],"history":["Military IR → industrial PdM (1980s-90s).","Affordable cameras (2010s) spread the practice."],"uses":["Electrical preventive maintenance.","Building diagnostics.","Mechanical troubleshooting."],"qa":[["What training is needed?","Level I thermography for credible work."],["Can it see through walls?","No — surface temperatures only."],["When scan?","Under load for electrical; with temperature differential for buildings."]]},{"title":"Oil Analysis","brief":"Oil analysis reads machine health from lubricant: wear metals, contamination, and degradation.","points":["Wear metals identify which component is wearing.","Contamination (water, fuel, dirt) reveals seal and filtration issues.","Trending matters more than single samples.","Sample correctly — bad samples lie."],"examples":["Rising iron predicting a gearbox failure.","Fuel dilution revealing injector problems."],"history":["Railroads pioneered it (1940s); aviation and industry followed.","Labs made it accessible to fleets."],"uses":["Fleet maintenance.","Industrial reliability.","Warranty and failure analysis."],"qa":[["How often sample?","Per manufacturer or quarterly for critical equipment."],["Can I sample myself?","Yes with proper technique — labs provide kits."],["What do results mean?","Labs flag abnormalities; trends guide action."]]},{"title":"Predictive Diagnostics","brief":"Predictive maintenance diagnoses future failures from current condition — fixing before breakdown.","points":["Condition monitoring (vibration, thermal, oil) feeds predictions.","P-F intervals: the time between detectable potential failure and functional failure.","Act in the P-F window — too early wastes, too late fails.","Not everything deserves prediction — criticality guides investment."],"examples":["A bearing replaced during planned downtime, not at 2 AM.","P-F intervals scheduling interventions optimally."],"history":["RCM (1970s, aviation) founded the discipline.","IoT sensors (2010s) scaled monitoring."],"uses":["Avoiding unplanned downtime.","Optimizing maintenance spend.","Safety in critical industries."],"qa":[["Predictive or preventive?","Predictive for critical/variable; preventive for simple/time-based."],["Is it expensive?","Program costs beat single unplanned failures in most plants."],["Where start?","Critical equipment with P-F intervals you can act on."]]},{"title":"Condition Monitoring","brief":"Condition monitoring watches equipment health continuously or periodically — the eyes of predictive maintenance.","points":["Techniques: vibration, thermal, ultrasound, oil, electrical.","Online (continuous) for critical; route-based for the rest.","Alarms need baselines — generic limits cause false alarms.","Integration with CMMS turns findings into work orders."],"examples":["Wireless sensors catching a pump failure trend.","Route data revealing plant-wide misalignment."],"history":["Portable instruments → wireless online (2010s).","Cloud analytics scaled interpretation."],"uses":["Reliability programs.","Energy and safety.","Maintenance optimization."],"qa":[["Which technique first?","Vibration for rotating equipment — the highest value."],["How many sensors?","Critical assets first; expand on ROI."],["Who analyzes?","Trained analysts — or managed services."]]},{"title":"Non-Destructive Testing (NDT)","brief":"NDT inspects without damaging: ultrasound, radiography, magnetic particle, dye penetrant, eddy current.","points":["UT finds internal flaws; RT images them; MT/PT find surface cracks.","Choose method by material, defect type, and access.","Certified technicians (ASNT levels) perform credible NDT.","Codes (ASME, API) mandate NDT in critical industries."],"examples":["UT finding pipeline corrosion before leaks.","Dye penetrant revealing a cracked weld."],"history":["WWII drove NDT development; codes standardized it.","Phased-array UT (2000s) advanced capability."],"uses":["Pressure vessels and pipelines.","Aerospace and bridges.","Manufacturing quality."],"qa":[["Which method?","Depends on material and suspected defect — consult the codes."],["Can I DIY NDT?","Credible NDT needs training and certification."],["How often inspect?","Per code and risk-based inspection programs."]]},{"title":"Visual Inspection","brief":"The oldest diagnostic: trained eyes finding what instruments miss — still the first and last step.","points":["Look for the abnormal: leaks, discoloration, damage, wear patterns.","Good lighting and access make or break inspection.","Document with photos — memory fades, images don't.","Know what 'normal' looks like to spot abnormal."],"examples":["A cracked belt spotted before it stranded a driver.","Corrosion found early, treated cheaply."],"history":["Inspection is as old as craftsmanship.","Checklists (aviation, medicine) made it reliable."],"uses":["Every trade and profession.","Preventive maintenance.","Quality control."],"qa":[["Isn't visual too basic?","It catches a huge share of issues — never skip it."],["How get better?","Study failure modes; inspect deliberately, not casually."],["What tools help?","Lights, mirrors, borescopes, cameras."]]},{"title":"Business Diagnostics","brief":"Business diagnostics assess organizational health: financial, operational, and strategic — finding what's really wrong.","points":["Financial ratios reveal liquidity, profitability, and leverage trends.","Operational metrics expose bottlenecks and waste.","Market analysis tests strategic positioning.","Culture and leadership often underlie the numbers."],"examples":["Ratio analysis revealing a cash-flow crisis behind profit.","Operational mapping finding the real bottleneck."],"history":["Financial analysis (early 20th c.); modern frameworks (Balanced Scorecard, etc.).","Consulting industrialized the practice."],"uses":["Turnarounds.","Investment due diligence.","Strategic planning."],"qa":[["Where start?","Cash flow — businesses die from cash, not accounting losses."],["Numbers or people?","Both — culture drives the numbers."],["DIY or consultant?","DIY for familiar ground; outside eyes for blind spots."]]},{"title":"Financial Diagnostics","brief":"Financial statement diagnosis: reading balance sheets, income, and cash flow for health and fraud.","points":["Cash flow tells the truth that earnings can hide.","Ratio trends beat single-period snapshots.","Red flags: revenue without cash, exploding receivables, opaque segments.","Footnotes often matter more than headlines."],"examples":["Cash-flow analysis exposing a 'profitable' company's distress.","Receivables growth flagging channel stuffing."],"history":["Graham and Dodd (1934) founded security analysis.","Forensic accounting grew after Enron-era scandals."],"uses":["Investing.","Lending decisions.","Fraud detection."],"qa":[["What ratio matters most?","Cash conversion and free cash flow — cash is fact."],["Can statements lie?","They can mislead legally — hence skepticism and footnotes."],["Where learn?","Graham/Dodd, then practice on real filings."]]},{"title":"Organizational Diagnostics","brief":"Diagnosing organizations: structure, culture, and processes — why companies underperform.","points":["Structure: does the org chart match how work flows?","Culture: what behaviors are actually rewarded?","Processes: where do handoffs break?","Diagnose before reorganizing — restructures without diagnosis repeat problems."],"examples":["A handoff map revealing where projects stall.","Culture interviews explaining why initiatives die."],"history":["Organizational development (1960s+).","Modern people-analytics added data."],"uses":["Turnarounds and transformations.","Merger integration.","Leadership development."],"qa":[["What's the usual root cause?","Misaligned incentives and unclear ownership."],["Surveys or interviews?","Both — surveys quantify, interviews explain."],["How long does it take?","Weeks for assessment; months for change."]]},{"title":"Educational Assessment","brief":"Educational diagnostics identify learning needs: what's understood, what's missing, and why.","points":["Formative assessment guides teaching; summative evaluates learning.","Diagnostic tests pinpoint specific skill gaps.","Misconceptions matter more than wrong answers.","Accommodations follow from accurate diagnosis."],"examples":["A math diagnostic revealing fraction gaps behind algebra struggles.","Reading assessment guiding intervention."],"history":["Standardized testing (early 20th c.); formative assessment research (1990s+).","Learning science refined diagnostic approaches."],"uses":["Targeted teaching.","Special education identification.","Curriculum improvement."],"qa":[["Testing or teaching?","Assessment should serve learning, not just measure it."],["What is formative assessment?","Ongoing checks that guide instruction."],["Are standardized tests diagnostic?","Weakly — they're better at ranking than diagnosing."]]},{"title":"Psychological Assessment","brief":"Psychological testing diagnoses mental health and cognitive functioning — with care and ethics.","points":["Clinical interviews remain the core; tests supplement.","Validated instruments beat intuition.","Cultural competence prevents misdiagnosis.","Assessment guides treatment, not labels."],"examples":["Testing clarifying ADHD versus anxiety.","Cognitive assessment guiding rehabilitation."],"history":["Binet's intelligence scale (1905) began modern testing.","Ethical standards evolved with the field."],"uses":["Treatment planning.","Educational and workplace accommodations.","Forensic and medical contexts."],"qa":[["Are online quizzes valid?","No — validated instruments administered properly only."],["Does diagnosis label people?","Done well, it guides help; stigma is the risk to manage."],["Who can assess?","Licensed psychologists and related professionals."]]},{"title":"Veterinary Diagnostics","brief":"Animal diagnostics adapt medical methods to non-speaking patients — observation is everything.","points":["History comes from owners; observation from the animal.","Species differences change everything — normal varies wildly.","Lab work and imaging parallel human medicine.","Behavioral changes are often the first sign."],"examples":["Lab work revealing kidney disease in a cat.","Lameness localized through systematic exam."],"history":["Veterinary medicine professionalized (18th-19th c.).","Diagnostics paralleled human advances."],"uses":["Pet health.","Livestock production.","Wildlife conservation."],"qa":[["Why so expensive?","Same technology as human medicine, without insurance pooling."],["When see a vet?","Behavior changes, appetite loss, or anything sudden."],["Can I diagnose at home?","Observe and report — diagnosis needs vets."]]},{"title":"Plant Disease Diagnostics","brief":"Plant pathology diagnoses crop and garden diseases: symptoms, signs, and lab confirmation.","points":["Symptoms (plant response) vs signs (pathogen visible) — learn the difference.","Abiotic disorders (nutrient, water) mimic diseases.","Lab diagnosis confirms before expensive treatment.","Extension services provide expert diagnosis."],"examples":["Lab testing distinguishing fungal from bacterial blight.","Nutrient deficiency corrected after ruling out disease."],"history":["Plant pathology (19th c., de Bary).","Molecular diagnostics modernized it."],"uses":["Crop protection.","Garden troubleshooting.","Biosecurity."],"qa":[["What's wrong with my plant?","Check water, light, and nutrients before assuming disease."],["Can I send a sample?","Yes — extension services accept them."],["Organic treatment?","Cultural controls first; targeted treatments second."]]},{"title":"Soil Diagnostics","brief":"Soil testing reveals fertility, pH, and structure — the foundation of growing.","points":["Test pH, nutrients, and organic matter before amending.","Sample correctly: multiple cores, right depth.","Texture (sand/silt/clay) determines management.","Retest every few years; amend based on results."],"examples":["A soil test revealing phosphorus excess from over-fertilizing.","pH adjustment unlocking nutrient availability."],"history":["Agricultural experiment stations (19th c.) began systematic testing.","Home kits and labs made it accessible."],"uses":["Gardening success.","Farming profitability.","Environmental protection."],"qa":[["When test?","Before planting new areas and every 2-3 years."],["Home kit or lab?","Lab for accuracy; kits for quick checks."],["What does pH affect?","Nutrient availability — wrong pH starves plants amid plenty."]]},{"title":"Water System Diagnostics","brief":"Diagnosing wells, pumps, and plumbing systems: pressure, flow, and quality.","points":["Pressure tanks, switches, and pumps form the system — test each.","Flow tests reveal well capacity.","Water quality testing protects health.","Electrical checks find pump failures."],"examples":["A pressure switch found behind 'no water'.","Flow testing sizing replacement equipment."],"history":["Rural water systems evolved with pump technology.","Diagnostics formalized with the trades."],"uses":["Well ownership.","Rural property maintenance.","Water quality assurance."],"qa":[["No water — where start?","Breaker, pressure switch, then pump."],["How often test water?","Annually for bacteria and nitrates."],["DIY or pro?","Electrical and deep-well work favor pros."]]},{"title":"Appliance Diagnostics","brief":"Appliance troubleshooting: systematic checks that fix most failures without a service call.","points":["Verify power and settings first — most 'failures' aren't.","Error codes point to subsystems; look them up.","Common failures: thermal fuses, pumps, belts, igniters.","Know when to stop — sealed systems and gas need pros."],"examples":["A thermal fuse explaining a dead dryer.","An error code leading to a clogged drain pump."],"history":["Appliances complexified with electronics (1990s+).","Online parts and videos enabled DIY."],"uses":["Saving service-call costs.","Extending appliance life.","Deciding repair vs replace."],"qa":[["What's usually wrong?","Power, then simple wear parts — check those first."],["Repair or replace?","If repair < 50% of replacement and unit < 2/3 lifespan, repair."],["Are error codes reliable?","They point to subsystems; verify with testing."]]},{"title":"Computer Diagnostics","brief":"PC troubleshooting: isolate hardware vs software, then narrow systematically.","points":["Won't boot? Power, POST, then OS — in order.","Intermittent issues: heat, RAM, and power supply lead suspects.","Safe mode and live USBs separate hardware from software.","Back up before invasive fixes."],"examples":["MemTest revealing bad RAM behind random crashes.","A failing drive cloned before it died."],"history":["POST cards and beep codes (1980s).","Built-in diagnostics (UEFI) modernized the process."],"uses":["Keeping PCs running.","Data preservation.","Upgrade decisions."],"qa":[["Where start?","What's changed? Then power → POST → OS."],["Hardware or software?","Safe mode/live USB test separates them."],["When reinstall?","After ruling out hardware — and with backups."]]},{"title":"Solar System Diagnostics","brief":"Solar PV troubleshooting: production drops have findable causes.","points":["Monitor production — drops reveal problems early.","Shade, soiling, and snow are the common culprits.","Inverter error codes guide electrical diagnosis.","Panel-level monitoring pinpoints underperformers."],"examples":["Soiling found behind a 15% production drop.","An inverter fault identified by its code."],"history":["Solar monitoring matured with the industry (2010s).","Panel-level electronics added granularity."],"uses":["Protecting solar investments.","Warranty claims with data.","System optimization."],"qa":[["Why did production drop?","Shade, dirt, snow, then equipment — check in order."],["How monitor?","Inverter apps; panel-level for precision."],["DIY or pro?","Cleaning and monitoring DIY; electrical pro."]]},{"title":"Septic System Diagnostics","brief":"Septic troubleshooting: distinguishing tank, drainfield, and plumbing issues.","points":["Slow drains everywhere suggest tank or field; one fixture suggests local.","Wet drainfield areas signal field failure.","Pumping history matters — neglected tanks kill fields.","Dye tests and cameras confirm suspicions."],"examples":["A full tank found behind whole-house slow drains.","Drainfield failure diagnosed by surfacing effluent."],"history":["Septic systems are century-old technology; diagnostics modernized slowly.","Regulations increasingly require inspections."],"uses":["Rural homeownership.","Property transactions.","Environmental protection."],"qa":[["How often pump?","Every 3-5 years typically."],["What kills drainfields?","Solids from unpumped tanks, and water overuse."],["DIY or pro?","Pumping and field work need pros."]]},{"title":"Roof Diagnostics","brief":"Roof assessment: finding leaks, wear, and remaining life without guesswork.","points":["Interior stains locate generally; roof inspection pinpoints.","Flashings fail before fields — check penetrations first.","Infrared finds wet insulation invisible to eyes.","Age plus condition determines repair vs replace."],"examples":["Flashing failure found behind a 'roof leak'.","Infrared mapping wet insulation for targeted repair."],"history":["Roofer craft is ancient; infrared and drones modernized assessment.","Manufacturer certifications standardized quality."],"uses":["Leak resolution.","Maintenance planning.","Insurance and real estate."],"qa":[["Repair or replace?","Age, extent, and layer count decide."],["Can I inspect myself?","Ground and attic checks yes; roof walking is risky."],["How long do roofs last?","Asphalt 20-30 years; metal 40-70; tile 50+."]]},{"title":"Foundation Diagnostics","brief":"Foundation assessment: distinguishing cosmetic cracks from structural threats.","points":["Crack orientation and width guide urgency.","Water is the enemy — manage drainage first.","Monitor movement before concluding.","Engineers diagnose; contractors repair."],"examples":["Drainage fixes resolving 'foundation problems'.","Monitoring proving seasonal vs progressive movement."],"history":["Foundation science matured with soil mechanics (20th c.).","Pier and stabilization technologies evolved."],"uses":["Homebuyer protection.","Maintenance prioritization.","Insurance claims."],"qa":[["Which cracks are bad?","Horizontal, wide (>1/4\"), or displacing."],["Can I fix it myself?","Drainage yes; structural repairs no."],["How much does repair cost?","Widely variable — get engineering assessment first."]]},{"title":"Diagnostic Documentation","brief":"Good diagnostics are written down: findings, tests, and reasoning — for the next person and yourself.","points":["Record symptoms, tests performed, and results — not just conclusions.","Photos document conditions words can't.","Note what was ruled out, not just what was found.","Future you (or the next tech) will thank present you."],"examples":["A documented intermittent fault saving hours on its return.","Photos proving pre-existing conditions."],"history":["Documentation standards grew with professional trades.","Digital tools eased capture and sharing."],"uses":["Continuity across visits and technicians.","Warranty and dispute evidence.","Learning from history."],"qa":[["What should I record?","Symptoms, tests, results, conclusions, and what was excluded."],["Paper or digital?","Digital for searchability; either beats memory."],["How detailed?","Enough that someone else could continue your work."]]},{"title":"Diagnostic Decision Making","brief":"Deciding under uncertainty: when to test more, when to act, and how to handle being wrong.","points":["Balance the cost of testing against the cost of being wrong.","Dangerous possibilities get ruled out first regardless of probability.","Decide in advance what results would change your mind.","Document reasoning — future review improves judgment."],"examples":["Ruling out the dangerous cause before the likely one.","Stopping testing when evidence converges."],"history":["Decision science (20th c.) informed professional judgment.","Checklists and protocols reduced error."],"uses":["Medicine, aviation, and engineering.","Management decisions.","Everyday troubleshooting."],"qa":[["How avoid bias?","Consider alternatives actively; seek disconfirming evidence."],["When act vs test?","When the cost of delay exceeds the value of more information."],["What if I'm wrong?","Design actions to be reversible; monitor outcomes."]]},{"title":"When to Call a Professional","brief":"Knowing your limits is diagnostic skill: safety, legality, and economics of DIY vs pro.","points":["Safety first: electricity, gas, structural, and medical have hard limits.","Legal limits: licensed trades exist for reasons.","Economic: pros' efficiency can beat DIY time costs.","Diagnose what you can; hand off with good information."],"examples":["A homeowner's clear symptom description speeding a pro's diagnosis.","Knowing gas work is never DIY."],"history":["Licensing grew with system complexity and safety knowledge.","DIY culture expanded with information access."],"uses":["Safety.","Cost-effectiveness.","Quality outcomes."],"qa":[["How decide?","Safety, then legal, then whether your time is well spent."],["Does DIY void warranties?","Sometimes — check before opening."],["How find a good pro?","Licensing, reviews, and clear diagnostic (not just repair) quotes."]]},{"title":"Diagnostic Ethics and Safety","brief":"Diagnostics carries responsibilities: honesty about uncertainty, safety during testing, and respect for people.","points":["Never fake certainty — state confidence levels honestly.","Testing must not endanger people or property.","In medicine, diagnosis affects lives — humility is mandatory.","Conflicts of interest (selling the cure) demand transparency."],"examples":["A mechanic declining an unnecessary repair.","A doctor saying 'I don't know yet' honestly."],"history":["Professional ethics codes address these duties.","Consumer protection laws back them."],"uses":["Trust in professions.","Patient and customer safety.","Professional integrity."],"qa":[["What if I'm unsure?","Say so, and say what would resolve it."],["Upselling vs honesty?","Recommend what's needed; disclose what's optional."],["Safety during diagnosis?","Plan for what could go wrong before testing."]]},{"title":"Acoustic Diagnostics","brief":"Listening as diagnosis: bearings, leaks, and structures all speak — if you know the language.","points":["Ultrasonic detectors hear leaks and electrical discharge humans can't.","Stethoscopes (mechanic's) isolate noises to components.","Changed sounds are the signal — know the baseline.","Record and compare; memory of sounds fades."],"examples":["Ultrasound finding a compressed-air leak worth thousands yearly.","A bearing's changing tone predicting failure."],"history":["Railroad wheel-tappers (19th c.) were early acoustic diagnosticians.","Ultrasonic instruments (late 20th c.) extended hearing."],"uses":["Leak detection.","Bearing monitoring.","Electrical discharge location."],"qa":[["What can ultrasound hear?","Leaks, corona, bearing friction — all above human hearing."],["Do I need training?","Basic use is easy; interpretation takes practice."],["Worth the investment?","Leak surveys alone often pay back instruments."]]},{"title":"Diagnostic Case Studies","brief":"Learning from real cases: how great diagnosticians solved the puzzling ones.","points":["Study solved cases to build pattern libraries.","Note the reasoning, not just the answer.","Failed cases teach as much as successes.","Discuss cases with peers — collective wisdom exceeds individual."],"examples":["A puzzling vibration solved by questioning assumptions.","A medical zebra caught by broadening the differential."],"history":["Case-based learning is ancient (Hippocratic cases).","Modern conferences and journals systematized sharing."],"uses":["Professional development.","Teaching diagnostic reasoning.","Building institutional knowledge."],"qa":[["Where find cases?","Journals, conferences, and experienced mentors."],["How study them?","Pause before the answer — reason it yourself first."],["Share my own?","Anonymized, yes — the field learns from shared experience."]]},{"title":"The Future of Diagnostics","brief":"Diagnostics is being transformed: AI assistance, continuous monitoring, and predictive power.","points":["AI augments pattern recognition across images, signals, and text.","Continuous monitoring catches drift before symptoms.","Predictive models estimate remaining useful life.","Human judgment remains central — AI proposes, people decide."],"examples":["AI flagging subtle imaging findings for radiologists.","Predictive models scheduling maintenance optimally."],"history":["Each era's tools seemed revolutionary; the method endures.","Current wave: data abundance meets machine learning."],"uses":["Earlier, more accurate diagnosis.","Preventing failures, not just fixing them.","Democratizing expert-level insight."],"qa":[["Will AI replace diagnosticians?","It changes the job — judgment, context, and responsibility remain human."],["What skills matter now?","Fundamentals plus data literacy — tools change, reasoning doesn't."],["What's hype vs real?","Real: pattern assistance. Hype: full autonomy soon."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-diagnostics-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('diagnostics',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();